code.source:
#include <iostream>
using namespace std;

void double_it(int n) {
    n = n * 2;
    cout << "Inside: " << n << endl;
}

int main() {
    int number = 10;
    double_it(number);
    cout << "Outside: " << number << endl;
    return 0;
}

#include <iostream>
using namespace std;

void swap_values(int a, int b) {
    int t = a;
    a = b;
    b = t;
}

int main() {
    int x = 1, y = 2;
    swap_values(x, y);
    cout << x << " " << y << endl;
    return 0;
}

